int main() {
    nlohmann::json src = nlohmann::json::array({2, 3});
    nlohmann::json j = nlohmann::json::array({1, 4});
    j.insert(j.begin() + 1, src.begin(), src.end());
    std::cout << j.dump() << std::endl;
    return 0;
}
